const jobs=()=>[...base,...state.custom];const getJob=id=>jobs().find(j=>j.id===+id);const getApp=id=>state.apps.find(a=>a.id===+id&&a.status!=='已取消');const terminal=['已取消','未通过','已婉拒'];const recruiting=['已投递','筛选中','待确认面试','待面试','面试完成','待确认录用'];const liveApps=()=>state.apps.filter(a=>!terminal.includes(a.status));const profile=()=>state.profile;function persist(){localStorage.setItem('zhoumo-preview-v2',JSON.stringify(state));$('#unread').textContent=Object.keys(state.chats).length||''}function toast(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').style.display='block';toastTimer=setTimeout(()=>$('#toast').style.display='none',3000)}function show(html){$('#modal-body').innerHTML=html;if(!modal.open)modal.showModal()}function navigate(p){page=p;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));render();window.scrollTo({top:0,behavior:'instant'})}function render(){persist();if(page==='jobs')renderJobs();if(page==='messages')renderMessages();if(page==='weekend')renderWeekend();if(page==='profile')renderProfile();if(page==='merchant')renderMerchant()}
const dateText=j=>j.day==='周六'?'10月31日':'11月1日';const income=j=>j.pay*j.hours;const score=j=>Math.max(60,99-Math.round(j.dist*4)-(profile().day!=='不限'&&profile().day!==j.day?18:0));const stageList=['待到岗','工作中','待结算','已结算'];function filteredJobs(){let list=jobs().filter(j=>!j.closed&&(category==='全部'||j.cat===category)&&(!query||(j.title+j.shop+j.tags.join('')+j.desc).includes(query))&&(jobTab!=='saved'||state.saved.includes(j.id))&&(profile().day==='不限'||j.day===profile().day)&&j.dist<=profile().distance&&j.pay>=profile().min&&(!onlyNew||j.tags.includes('新人友好'))&&(!onlyMeal||j.tags.includes('提供工作餐'))&&(timeFilter==='all'||(timeFilter==='morning'?j.start<12:timeFilter==='afternoon'?j.start>=12:j.hours<=4)));return list.sort((a,b)=>sort==='pay'?b.pay-a.pay:sort==='distance'?a.dist-b.dist:sort==='income'?income(b)-income(a):sort==='hours'?a.hours-b.hours:score(b)-score(a))}
function renderJobs(){const list=filteredJobs();if(!list.some(j=>j.id===selected))selected=list[0]?.id||null;$('#app').innerHTML=`<div class="page-heading"><h1>周末兼职</h1><div class="quick-stats"><span>不收报名费</span><span>班次收入透明</span><span>支持直接沟通</span></div></div><section class="search-section" aria-label="岗位搜索和筛选"><form class="search-main" onsubmit="event.preventDefault();query=this.query.value.trim();renderJobs()"><button type="button" class="school-pick" onclick="campusInfo()">⌖ 江城大学 ▾</button><label class="sr-only" for="query">搜索岗位、店铺或技能</label><input id="query" name="query" placeholder="搜索岗位、店铺或技能" value="${esc(query)}"><button class="primary">搜索兼职</button></form><div class="filter-row"><span class="filter-label">岗位</span>${['全部','餐饮零售','活动协助','技能兼职','文教助教','办公协助','运动服务','校园服务'].map(c=>`<button class="${category===c?'selected':''}" onclick="category='${c}';renderJobs()">${c}</button>`).join('')}</div><div class="filter-divider"></div><div class="filter-row"><span class="filter-label">筛选</span><select aria-label="工作日期" onchange="state.profile.day=this.value;persist();renderJobs()">${['不限','周六','周日'].map(d=>`<option value="${d}" ${profile().day===d?'selected':''}>${d==='不限'?'本周末 · 全部':d+' '+(d==='周六'?'10/31':'11/01')}</option>`).join('')}</select><select aria-label="通勤距离" onchange="state.profile.distance=+this.value;persist();renderJobs()">${[1,2,3,5].map(n=>`<option value="${n}" ${+profile().distance===n?'selected':''}>距校 ${n}km 内</option>`).join('')}</select><select aria-label="最低时薪" onchange="state.profile.min=+this.value;persist();renderJobs()">${[0,20,25,30,35,40].map(n=>`<option value="${n}" ${+profile().min===n?'selected':''}>${n?'时薪 ¥'+n+' 起':'时薪不限'}</option>`).join('')}</select><select aria-label="工作时段" onchange="timeFilter=this.value;visibleCount=12;renderJobs()">${[['all','时段不限'],['morning','上午开始'],['afternoon','下午开始'],['short','4小时及以内']].map(([v,t])=>`<option value="${v}" ${timeFilter===v?'selected':''}>${t}</option>`).join('')}</select><button class="${onlyNew?'selected':''}" onclick="onlyNew=!onlyNew;renderJobs()">${onlyNew?'✓ ':''}新人友好</button><button class="${onlyMeal?'selected':''}" onclick="onlyMeal=!onlyMeal;renderJobs()">${onlyMeal?'✓ ':''}提供工作餐</button><button class="text-btn" onclick="resetFilters()">重置</button></div></section><div class="result-toolbar"><div class="tabs"><button class="${jobTab==='recommended'?'selected':''}" onclick="jobTab='recommended';renderJobs()">为你推荐</button><button class="${jobTab==='saved'?'selected':''}" onclick="jobTab='saved';renderJobs()">我的收藏 <small>${state.saved.length}</small></button></div><div class="sort-tools"><select aria-label="岗位排序" onchange="sort=this.value;renderJobs()"><option value="match" ${sort==='match'?'selected':''}>匹配优先</option><option value="pay" ${sort==='pay'?'selected':''}>时薪最高</option><option value="distance" ${sort==='distance'?'selected':''}>距离最近</option><option value="income" ${sort==='income'?'selected':''}>班次收入最高</option><option value="hours" ${sort==='hours'?'selected':''}>工时最短</option></select><button class="text-btn" onclick="view=view==='list'?'map':'list';renderJobs()">${view==='list'?'⌖ 附近示意图':'☷ 列表视图'}</button></div></div><div class="result-caption">${list.length} 个符合条件的岗位 · 本周末 10.31—11.01 · 岗位及回复时效为演示数据</div><div class="job-layout">${view==='map'?mapView(list):`<div class="job-list">${list.length?list.slice(0,visibleCount).map(jobCard).join('')+(list.length>visibleCount?`<button class="secondary full" onclick="visibleCount+=12;renderJobs()">加载更多岗位（还有 ${list.length-visibleCount} 个）</button>`:''):emptyJobs()}</div><div id="detail-slot">${selected?detailHTML(getJob(selected)):''}</div>`}<aside class="sidebar">${sidebar()}</aside></div>${compare.length?`<div class="compare-bar"><span>已选 ${compare.length}/2 个岗位 · 比一比再决定</span><button onclick="compareJobs()">查看对比 →</button><button onclick="compare=[];renderJobs()" aria-label="清空对比">×</button></div>`:''}`}
function resetFilters(){category='全部';query='';timeFilter='all';visibleCount=12;onlyNew=false;onlyMeal=false;state.profile.day='不限';state.profile.distance=3;state.profile.min=0;persist();renderJobs()}
function jobCard(j){const a=getApp(j.id);return `<article class="job-card ${j.id===selected?'chosen':''}" tabindex="0" role="button" aria-label="查看${esc(j.title)}" onkeydown="if(event.key==='Enter')selectJob(${j.id})" onclick="selectJob(${j.id})"><div class="job-title-line"><h3>${esc(j.title)}</h3><span class="money">${j.pay}<small>元/时</small></span></div><div class="subline">${j.day} ${j.time} <span style="color:#d8e3da">｜</span> 距校 ${j.dist}km <span style="color:#d8e3da">｜</span> 预计 ¥${income(j)}</div><div class="tags">${j.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}<span class="tag green">${a?a.status:'次日结算'}</span></div><div class="job-shop"><div class="shop-icon" style="--shop-bg:${j.bg}">${j.icon}</div><div><div class="shop-name">${esc(j.shop)}</div><small>${j.recruiter} · ${j.reply}</small></div><span class="match-chip">${score(j)}% 匹配</span></div><div class="mobile-detail"><span class="text-btn">查看详情与班次 →</span></div></article>`}
function selectJob(id){selected=id;if(window.innerWidth<=590){show(detailHTML(getJob(id)))}else{renderJobs()}}
function detailHTML(j){const a=getApp(j.id),saved=state.saved.includes(j.id);return `<section class="detail-pane"><div class="detail-top"><div class="eyebrow">${j.closed?'招聘已结束':'WEEKEND OPPORTUNITY'} · ${j.slots}个名额</div><h2>${esc(j.title)}</h2><div class="money">¥${j.pay}<small> / 小时</small></div><div class="meta">${esc(j.shop)}<br>${j.day} ${dateText(j)} · ${j.time} · 距校 ${j.dist}km</div><div class="detail-actions"><button class="primary" onclick="startChat(${j.id})">${state.chats[j.id]?'继续沟通':'和店长聊聊'}</button><button class="secondary" onclick="${a?"closeAndGo('weekend')":'applyJob('+j.id+')'}">${a?'查看进度':'投递简历'}</button><button class="icon-button" aria-label="${saved?'取消收藏':'收藏岗位'}" onclick="toggleSave(${j.id})">${saved?'★':'☆'}</button></div></div><div class="detail-body"><h3 class="section-title">为什么推荐给你</h3><p class="job-description">${j.dist<=1?'距离校门不足1公里，步行通勤更轻松。':'位于校园生活圈内，单次通勤范围符合你的偏好。'}${j.tags.includes('新人友好')?'无需兼职经历。':'更适合已有相关技能、希望积累实践经历的同学。'} <button class="text-btn" onclick="matchingInfo(${j.id})">匹配依据 ⓘ</button></p><h3 class="section-title">班次安排</h3><div class="spec-grid"><div><small>工作时间</small>${j.day} ${j.time}</div><div><small>工作地点</small>${esc(j.place)}</div><div><small>本班工时</small>${j.hours}小时 · 无默认加班</div><div><small>招募人数</small>${j.slots}人 · ${j.closed?'已关闭':'招募中'}</div></div><h3 class="section-title">工作内容</h3><p class="job-description">${esc(j.desc)}</p><h3 class="section-title">岗位要求</h3><p class="job-description">${esc(j.requirements)}</p><h3 class="section-title">薪资明细</h3><div class="wage-box"><div class="line"><span>时薪 × 约定工时</span><span>¥${j.pay} × ${j.hours}小时</span></div><div class="line"><span>报名费 / 押金</span><span>¥0 / ¥0</span></div><div class="line total"><span>本班次预计到手</span><b>¥${income(j)}</b></div><div class="line"><span>结算方式</span><span>双方确认工时后次日结算</span></div></div><div class="recruiter"><div class="avatar">${j.recruiter[0]}</div><div><b>${j.recruiter}</b><small>门店负责人 · 资料核验（演示）</small></div><button class="text-btn" onclick="startChat(${j.id})">直接沟通 ↗</button></div><div class="safety-inline">盾 ✓ 不收押金，不收报名费。切勿向陌生账号转账。<button class="text-btn" onclick="reportJob(${j.id})">举报</button><br>模拟岗位与认证，不代表真实用工、资金或安全保障。</div><div class="comparison"><button class="text-btn" onclick="addCompare(${j.id})">${compare.includes(j.id)?'✓ 已加入对比':'＋ 加入岗位对比'}</button><button class="text-btn" onclick="safetyGuide()">安心兼职指南</button></div></div></section>`}
function sidebar(){const completion=profileCompletion();return `<div class="side-panel"><div class="profile-snippet"><div class="avatar">${esc(profile().name[0]||'林')}</div><div><b>${esc(profile().name)}，周末好 ☀</b><small>${esc(profile().school)} · ${esc(profile().grade)}</small></div></div><div class="progress-track"><span style="width:${completion}%"></span></div><div class="aside-label"><span>简历完整度</span><b>${completion}%</b></div><button class="aside-link" onclick="navigate('profile')">编辑简历 →</button><h3>我的空闲时间</h3><div class="availability">${(profile().day==='不限'?['周六','周日']:[profile().day]).map(d=>`<div class="day-block">${d}<small>09:00—18:00</small></div>`).join('')}</div><button class="aside-link" onclick="editAvailability()">调整时间与期望 ↗</button></div><div class="side-panel advice"><h3>应聘提示</h3><p>工资怎么算、具体做什么、几点到几点，都在报名前说清楚。</p><button onclick="safetyGuide()">查看避坑指南 →</button></div><div class="side-panel"><h3 style="margin-top:0">应聘流程</h3><div class="mini-step"><span>1</span> 查看岗位，投递简历</div><div class="mini-step"><span>2</span> 简历筛选，面试沟通</div><div class="mini-step"><span>3</span> 确认录用，到岗履约</div></div>`}
function emptyJobs(){return `<div class="empty"><strong>${jobTab==='saved'?'这里还没有符合条件的收藏':'暂时没有合适的岗位'}</strong><p>试试放宽日期、通勤范围或搜索关键词。</p><button class="secondary" onclick="resetFilters()">重置筛选</button></div>`}
function toggleSave(id){if(state.saved.includes(id))state.saved=state.saved.filter(x=>x!==id);else state.saved.push(id);persist();if(page==='jobs'){if(modal.open)$('#modal-body').innerHTML=detailHTML(getJob(id));renderJobs()}toast(state.saved.includes(id)?'已收藏，可在「我的收藏」查看':'已取消收藏')}
function addCompare(id){if(compare.includes(id))compare=compare.filter(x=>x!==id);else if(compare.length<2)compare.push(id);else{toast('一次对比两个岗位，请先移除其中一个');return}if(modal.open)modal.close();renderJobs();toast(compare.includes(id)?'已加入对比':'已移出对比')}
function compareJobs(){if(compare.length<2){toast('再选一个岗位，就可以开始对比');return}show(`<h2>把两个选择放在一起看</h2><div class="compare-grid">${compare.map(id=>{const j=getJob(id);return `<div class="compare-column"><h3>${j.icon} ${esc(j.title)}</h3><div>时薪 <b>¥${j.pay}</b><br>本班收入 <b>¥${income(j)}</b></div><div>${j.day} ${j.time}<br>约定工时 ${j.hours}小时</div><div>距校 ${j.dist}km<br>${j.tags.map(esc).join(' · ')}</div><div>${esc(j.requirements)}</div><button class="primary full" onclick="modal.close();selected=${id};selectJob(${id})">查看这个岗位</button></div>`}).join('')}</div><p>比较的是具体班次，无默认加班；正式报名前仍需确认岗位要求和通勤安排。</p>`)}
function mapView(list){const positions=[[23,34],[64,58],[18,65],[74,31],[55,76],[72,77],[26,78],[30,17]];return `<section class="map-panel" aria-label="校园周边岗位示意图"><div class="map-caption">⌖ 校园周边示意图 · 非真实地图与导航<br><small>点选薪资标记，查看岗位与工作地点</small></div><div class="map-road"></div><div class="map-road vertical"></div><div class="campus">江城大学</div>${list.map((j,i)=>`<button class="map-pin" style="left:${positions[i%8][0]}%;top:${positions[i%8][1]}%" onclick="show(detailHTML(getJob(${j.id})))">${j.icon} ¥${j.pay}/时</button>`).join('')}<div class="map-legend">距离为演示数据 · 仅辅助理解校园生活圈<br>当前 ${list.length} 个符合筛选条件的岗位</div></section>`}
function matchingInfo(id){const j=getJob(id);show(`<h2>${score(j)}% 匹配，怎么算？</h2><p>先按你设置的日期、通勤距离、最低时薪筛选，再用距离规则排序。技能要求仍需你与商家确认。</p><div class="logic-grid"><div><b>时间契合</b>岗位：${j.day} ${j.time}<br>你的空闲：${profile().day==='不限'?'周六、周日':profile().day} 09:00—18:00</div><div><b>通勤范围</b>距校 ${j.dist}km<br>期望 ${profile().distance}km 内</div><div><b>时薪预期</b>岗位 ¥${j.pay}/小时<br>最低要求 ${profile().min?'¥'+profile().min+'/小时':'不限'}</div><div><b>分数规则</b>99 − 距离(km)×4 的四舍五入值；日期不符再减18，最低60。本页已先筛去不合日期的岗位。</div></div><p>这是可解释规则的演示分数，未接入真实 AI 模型，也不代表录用概率。</p>`)}
function applyJob(id){const j=getJob(id);if(j.closed){toast('这个岗位已结束招聘');return}if(getApp(id)){closeAndGo('weekend');return}const conflict=liveApps().find(a=>{const x=getJob(a.id);return ['待到岗','工作中','待结算'].includes(a.status)&&x.day===j.day&&x.start<j.end&&j.start<x.end});if(conflict){show(`<h2>这两个班次时间重叠了</h2><p>你已报名「${esc(getJob(conflict.id).title)}」：${getJob(conflict.id).day} ${getJob(conflict.id).time}。<br>新班次：${j.day} ${j.time}。</p><div class="notice orange">为避免无法到岗，请先调整已有报名，再选择新班次。</div><button class="primary full" onclick="closeAndGo('weekend')">查看已有报名</button>`);return}show(`<h2>确认投递</h2><div class="notice">${esc(j.title)}<br>${j.day} ${dateText(j)} ${j.time} · ${j.hours}小时<br>约定时薪 ¥${j.pay} · 本班预计收入 ¥${income(j)}</div><p>将向商家展示你的演示简历：${esc(profile().name)} / ${esc(profile().school)} / ${esc(profile().skills||'暂无技能标签')}。不包含真实电话或证件。</p><form onsubmit="submitApplication(event,${id})"><label class="checkbox"><input type="checkbox" required>已读工作内容、班次与结算约定，能按时到岗</label><label class="checkbox"><input type="checkbox" required>演示角色为已满18周岁的在校学生</label><button class="primary full">确认投递简历</button></form><p>本作品仅演示撮合流程，不产生真实用工或付款。</p>`)}
function submitApplication(e,id){e.preventDefault();state.apps=state.apps.filter(a=>a.id!==id||a.status!=='已取消');state.apps.push({id,status:'已投递',review:null,submittedAt:Date.now()});persist();modal.close();navigate('weekend');toast('简历已投递，等待商家筛选')}
function closeAndGo(p){if(modal.open)modal.close();navigate(p)}
function startChat(id){const j=getJob(id);if(!state.chats[id])state.chats[id]=[{from:'shop',text:`你好，我是${j.recruiter}。我们在招${j.day}${j.time}的「${j.title}」，时薪¥${j.pay}。你想先了解哪方面？` }];activeChat=id;if(modal.open)modal.close();navigate('messages')}
function renderMessages(){const ids=Object.keys(state.chats).map(Number);if(!activeChat||!ids.includes(activeChat))activeChat=ids[0];const j=getJob(activeChat);$('#app').innerHTML=`<div class="page-heading"><div><h1>消息中心</h1></div><button class="secondary" onclick="navigate('jobs')">继续找兼职 →</button></div><div class="messages-layout"><aside class="threads"><div class="threads-heading">沟通中的岗位 <small style="color:#94a590">${ids.length}</small></div>${ids.map(id=>{const x=getJob(id),msgs=state.chats[id];return `<div class="thread ${id===activeChat?'chosen':''}" tabindex="0" role="button" aria-label="与${x.recruiter}的对话" onclick="activeChat=${id};renderMessages()" onkeydown="if(event.key==='Enter'){activeChat=${id};renderMessages()}"><div class="avatar">${x.recruiter[0]}</div><div><b>${x.recruiter}</b><small>${esc(x.shop)}</small><p>${esc(msgs[msgs.length-1].text)}</p></div></div>`}).join('')||'<div style="padding:23px;color:#94a58f;font-size:11px">还没有对话，从一个感兴趣的岗位开始吧。</div>'}</aside>${j?`<section class="chat-pane"><div class="chat-header"><div><h2>${j.recruiter} · ${esc(j.shop)}</h2><small>演示店长 · 自动模拟回复，非真人在线</small></div><button class="text-btn" onclick="reportJob(${j.id})">举报</button></div><div class="chat-job"><span>${esc(j.title)} · ${j.day} ${j.time} · ¥${j.pay}/时</span><button class="text-btn" onclick="show(detailHTML(getJob(${j.id})))">岗位详情 ↗</button></div><div class="chat-history" id="chat-history"><div class="chat-note">演示对话仅保存在此浏览器，请勿输入真实联系方式或敏感信息。</div>${state.chats[j.id].map(m=>`<div class="bubble-wrap ${m.from==='me'?'mine':''}">${m.from==='shop'?`<div class="avatar">${j.recruiter[0]}</div>`:''}<div class="bubble">${esc(m.text)}</div></div>`).join('')}</div><div class="chat-input"><div class="quick-replies">${['没有经验可以吗？','什么时候结算？','工作具体做什么？'].map(t=>`<button onclick="sendMessage(${j.id},'${t}')">${t}</button>`).join('')}</div><form class="chat-compose" onsubmit="event.preventDefault();sendMessage(${j.id},this.message.value)"><label class="sr-only" for="chat-message">给店长发消息</label><input id="chat-message" name="message" placeholder="聊一聊你关心的问题…" maxlength="300" required><button class="primary">发送</button></form><div class="actions" style="margin-top:12px"><button class="light-btn" onclick="${getApp(j.id)?"navigate('weekend')":'applyJob('+j.id+')'}">${getApp(j.id)?'查看报名进度':'聊清楚了，投递这个班次 →'}</button></div></div></section>`:`<div class="empty" style="border:0;display:grid;place-content:center"><strong>暂无对话</strong><p>点击岗位中的「和店长聊聊」，先了解再报名。</p><button class="primary" onclick="navigate('jobs')">去找兼职</button></div>`}</div>`;if($('#chat-history'))$('#chat-history').scrollTop=$('#chat-history').scrollHeight}
function sendMessage(id,text){text=text.trim();if(!text)return;const j=getJob(id);state.chats[id].push({from:'me',text});let reply;if(/经验|新手|第一次/.test(text))reply=j.tags.includes('新人友好')?'可以，没有相关经验也能报名。到岗后会先做岗位指导，记得阅读工作内容并确认能完成哦。':'这个岗位需要基础经验。具体要求是：'+j.requirements;else if(/结算|工资|薪资|钱|押金/.test(text))reply=`本班次为¥${j.pay}/小时，共${j.hours}小时，预计¥${income(j)}。双方确认工时后次日结算，不收任何押金或报名费。`;else if(/内容|做什么|工作/.test(text))reply=j.desc;else if(/时间|几点|班次|到岗/.test(text))reply=`约定班次是${j.day}${j.time}，请提前10分钟到场。当前演示不支持议价或修改班次，可选择其他更适合的岗位。`;else reply='你的消息已记入演示对话。此处不是实时客服；可以点击上方快捷问题，体验经验要求、工作内容与结算时间的模拟回复。';state.chats[id].push({from:'shop',text:reply});persist();renderMessages()}
function renderWeekend(){const active=liveApps(),pending=active.filter(a=>recruiting.includes(a.status)).length,unfinished=active.filter(a=>stageList.slice(0,3).includes(a.status));let shown=state.apps.filter(a=>weekTab==='all'||(weekTab==='recruit'?recruiting.includes(a.status):weekTab==='interview'?['待确认面试','待面试','面试完成'].includes(a.status):weekTab==='upcoming'?['待到岗','工作中'].includes(a.status):weekTab==='settle'?a.status==='待结算':weekTab==='ended'?terminal.includes(a.status):a.status==='已结算'));$('#app').innerHTML=`<div class="page-heading"><h1>应聘与排班</h1><button class="primary" onclick="navigate('jobs')">查看岗位 →</button></div><div class="metrics"><div class="metric"><small>应聘中</small><strong>${pending}</strong><em>简历筛选、面试与录用确认</em></div><div class="metric"><small>待履约 / 待结算</small><strong>${unfinished.length}</strong><em>双方确认录用后的班次</em></div><div class="metric"><small>待结算预计收入</small><strong>¥${unfinished.reduce((s,a)=>s+income(getJob(a.id)),0)}</strong><em>按约定完整班次计算</em></div><div class="metric"><small>已结算收入</small><strong style="color:var(--teal)">¥${state.settled}</strong><em>模拟账目，不产生实际付款</em></div></div><div class="notice">演示流程：在商家端筛选简历、邀请面试或发送录用意向；学生确认面试和录用后再进入排班。简单岗位可免面试快速录用。两端仅在当前浏览器共享数据。</div><div class="two-col"><section><div class="tabs application-tabs">${[['all','全部'],['recruit','应聘中'],['interview','面试'],['upcoming','待履约'],['settle','待结算'],['done','已完成'],['ended','已结束']].map(([v,t])=>`<button class="${weekTab===v?'selected':''}" onclick="weekTab='${v}';renderWeekend()">${t}</button>`).join('')}</div>${shown.length?shown.map(orderCard).join(''):`<div class="empty"><strong>暂无对应记录</strong><button class="secondary" onclick="navigate('jobs')">查看岗位</button></div>`}</section><aside><div class="panel"><h3 class="section-title">面试安排</h3>${active.filter(a=>['待确认面试','待面试'].includes(a.status)).map(a=>`<div class="calendar-block">${esc(getJob(a.id).title)}<br>${esc(a.interview?.date)} ${esc(a.interview?.time)}<br>${esc(a.interview?.method)} · ${a.status}</div>`).join('')||'<p style="font-size:11px;color:#899b85">暂无面试安排</p>'}</div><div class="panel" style="margin-top:15px"><h3 class="section-title">本周末排班</h3><div class="calendar">${['周六','周日'].map(d=>`<div class="calendar-day"><h3>${d} <small>${d==='周六'?'10/31':'11/01'}</small></h3>${active.filter(a=>stageList.includes(a.status)&&getJob(a.id).day===d).map(a=>{const j=getJob(a.id);return `<div class="calendar-block">${j.time}<br>${esc(j.title)}<br>${a.status}</div>`}).join('')||'<span style="font-size:10px;color:#9aaa93">暂无已确认班次</span>'}</div>`).join('')}</div></div></aside></div>`}

function orderCard(a){const j=getJob(a.id),offerAccepted=stageList.includes(a.status),rejected=terminal.includes(a.status),recruitIndex={已投递:0,筛选中:1,待确认面试:2,待面试:2,面试完成:2,待确认录用:3,待到岗:3,工作中:3,待结算:3,已结算:3}[terminal.includes(a.status)?(a.previousStatus||'已投递'):a.status]??-1;const recruitSteps=['已投递','简历筛选',a.fastTrack?'免面试':'面试','录用确认'];const note={已投递:'简历已投递，等待商家查看。',筛选中:'商家正在筛选简历。',待确认面试:'商家已发出面试邀请，请确认时间。',待面试:'面试时间已确认，请按约参加。',面试完成:'面试已结束，等待商家反馈结果。',待确认录用:'商家已发送录用意向，请确认班次及薪资。',待到岗:`到岗地点：${j.place}。请提前10分钟到场，联系${j.recruiter}。`,工作中:'已签到，完成班次后确认工时并签退。',待结算:`已提交 ${j.hours} 小时工时，等待商家核对。`,已结算:'本班次工时已确认，模拟收入已入账。',未通过:'本次应聘未通过。'+(a.rejection?' 原因：'+a.rejection:''),已婉拒:'你已婉拒本次录用。',已取消:'你已撤回本次应聘。'}[a.status];return `<article class="order-card"><div class="order-heading"><div><h3>${j.icon} ${esc(j.title)}</h3><small>${esc(j.shop)} · ${j.day} ${j.time} · ¥${income(j)}</small></div><span class="status ${rejected?'gray':''}">${a.status}</span></div><div class="process-label">求职进度${a.fastTrack?' · 快速录用':''}</div><div class="timeline">${recruitSteps.map((t,i)=>`<span class="${i<=recruitIndex?'done':''}">${t}</span>`).join('')}</div>${offerAccepted?`<div class="process-label">到岗履约</div><div class="timeline">${stageList.map((t,i)=>`<span class="${i<=stageList.indexOf(a.status)?'done':''}">${t}</span>`).join('')}</div>`:''}<p class="process-note">${esc(note||'')}</p>${a.interview&&!a.fastTrack?`<div class="interview-info">面试：${esc(a.interview.date)} ${esc(a.interview.time)} · ${esc(a.interview.method)}<br>地点 / 方式：${esc(a.interview.location)}${a.interview.note?'<br>备注：'+esc(a.interview.note):''}</div>`:''}<div class="order-foot"><span>不收报名费 · 约定时薪 ¥${j.pay}</span><div>${recruiting.includes(a.status)||a.status==='待到岗'?`<button class="text-btn" onclick="cancelApplication(${j.id})">撤回申请</button>`:''}${a.status==='待确认面试'?`<button class="primary" onclick="updateStatus(${j.id},'待面试')">确认参加面试</button>`:a.status==='待确认录用'?`<button class="secondary" onclick="declineOffer(${j.id})">婉拒</button><button class="primary" onclick="acceptOffer(${j.id})">确认录用</button>`:a.status==='待到岗'?`<button class="primary" onclick="updateStatus(${j.id},'工作中')">演示签到</button>`:a.status==='工作中'?`<button class="primary" onclick="signout(${j.id})">演示签退</button>`:a.status==='已结算'?`<button class="secondary" onclick="reviewShift(${j.id})">${a.review?'查看评价':'评价兼职'}</button>`:`<button class="secondary" onclick="startChat(${j.id})">联系店长</button>`}</div></div></article>`}

function updateStatus(id,status){const a=getApp(id);if(!a){toast('未找到应聘记录');return}const allowed={'已投递':['筛选中','待确认面试','待确认录用','未通过','已取消'],'筛选中':['待确认面试','待确认录用','未通过','已取消'],'待确认面试':['待面试','已取消','未通过'],'待面试':['面试完成','已取消','未通过'],'面试完成':['待确认录用','未通过','已取消'],'待确认录用':['待到岗','已婉拒','已取消'],'待到岗':['工作中','已取消'],'工作中':['待结算'],'待结算':['已结算']};if(!allowed[a.status]?.includes(status)){toast('当前状态无法执行此操作');return}if(status==='已结算')state.settled+=income(getJob(id));a.previousStatus=a.status;a.status=status;a.history=a.history||[];a.history.push({status,time:Date.now()});persist();render();toast('进度已更新：'+status)}
function acceptOffer(id){const j=getJob(id),conflict=liveApps().find(a=>a.id!==id&&['待到岗','工作中','待结算'].includes(a.status)&&getJob(a.id).day===j.day&&getJob(a.id).start<j.end&&j.start<getJob(a.id).end);if(conflict){toast('与已确认班次「'+getJob(conflict.id).title+'」冲突，请先调整排班');return}show(`<h2>确认接受录用？</h2><p>${esc(j.title)}<br>${j.day} ${j.time} · ${j.hours}小时<br>时薪 ¥${j.pay} · 班次收入 ¥${income(j)}</p><div class="notice">这是演示确认，不构成真实用工合同。确认后进入周末排班。</div><button class="primary full" onclick="updateStatus(${id},'待到岗');modal.close()">接受演示录用</button>`)}
function declineOffer(id){show(`<h2>婉拒这次录用？</h2><p>本次应聘将结束，商家端同步显示已婉拒。</p><div class="actions"><button class="secondary" onclick="modal.close()">返回</button><button class="primary" onclick="updateStatus(${id},'已婉拒');modal.close()">确认婉拒</button></div>`)}

function cancelApplication(id){show(`<h2>确定取消这个班次？</h2><p>取消后释放报名名额。已录用的班次应尽早通知商家；本演示不收取费用。</p><div class="actions"><button class="secondary" onclick="modal.close()">保留班次</button><button class="primary" onclick="updateStatus(${id},'已取消');modal.close()">确认取消</button></div>`)}
function signout(id){const j=getJob(id);show(`<h2>确认本次工作记录</h2><p>${esc(j.title)}<br>${j.day} ${j.time}<br>本演示按约定 ${j.hours} 小时 × ¥${j.pay} 生成 ¥${income(j)} 待结算记录。</p><div class="notice orange">这是模拟签到签退，不采集定位。真实上线应支持双方核实实际工时；若工时不一致，请先提交争议。</div><div class="actions"><button class="secondary" onclick="reportJob(${id})">工时有异议</button><button class="primary" onclick="updateStatus(${id},'待结算');modal.close()">确认工时并签退</button></div>`)}
function reviewShift(id){const a=getApp(id);if(a.review){show(`<h2>你的兼职评价</h2><p>${esc(a.review.rating)}</p><p>${esc(a.review.text)}</p>`);return}show(`<h2>为这次周末经历打个分</h2><form onsubmit="event.preventDefault();getApp(${id}).review={rating:this.rating.value,text:this.review.value.trim()};persist();modal.close();renderWeekend();toast('评价已保存')"><label class="field">整体体验<select name="rating"><option>★★★★★ 很满意</option><option>★★★★ 满意</option><option>★★★ 一般</option><option>★★ 需要改进</option><option>★ 不满意</option></select></label><label class="field">工作内容、工时或结算体验<textarea name="review" maxlength="200" required placeholder="写下你的体验，帮助后来的同学"></textarea></label><button class="primary full">提交演示评价</button></form>`)}
function profileCompletion(){return Math.round(['name','school','grade','skills','intro','experience'].filter(k=>profile()[k]?.trim()).length/6*100)}
function renderProfile(){$('#app').innerHTML=`<div class="page-heading"><div><h1>我的简历</h1></div></div><div class="two-col"><section class="panel"><div class="profile-topper"><div class="avatar">${esc(profile().name[0]||'林')}</div><div><h2>${esc(profile().name)}</h2><p>${esc(profile().school)} · ${esc(profile().grade)}</p></div><span class="status" style="margin-left:auto">演示身份</span></div><form onsubmit="saveProfile(event)"><div class="form-grid"><label class="field">展示昵称<input name="name" value="${esc(profile().name)}" maxlength="12" required></label><label class="field">年级<select name="grade">${['大一','大二','大三','大四','研究生'].map(x=>`<option ${profile().grade===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field wide">学校（当前演示校园）<input value="江城大学" readonly></label><label class="field wide">技能与特长<input name="skills" maxlength="80" value="${esc(profile().skills)}" placeholder="例如：沟通表达、摄影、活动组织"></label><label class="field wide">简单介绍自己<textarea name="intro" maxlength="250" required>${esc(profile().intro)}</textarea></label><label class="field wide">兼职或社团经历<textarea name="experience" maxlength="250">${esc(profile().experience)}</textarea></label></div><div class="notice">使用虚构信息体验即可。请勿填写真实手机号、身份证、住址或其他敏感信息。</div><button class="primary">保存演示简历</button></form></section><aside><div class="panel"><h3 class="section-title">我的求职期望</h3><p style="font-size:12px;color:#7d9479;line-height:2">可工作日期：${profile().day==='不限'?'周六、周日':profile().day}<br>可用时段：09:00—18:00<br>通勤范围：距校 ${profile().distance}km 内<br>最低时薪：${profile().min?'¥'+profile().min+'/小时':'不限'}</p><button class="secondary full" onclick="editAvailability()">调整求职期望</button></div><div class="side-panel advice" style="margin-top:15px"><h3>简历可见范围</h3><p>当前简历仅在此浏览器保存。报名后在商家演示端可见，不会进入公开人才库。未接入真实身份核验或附件上传。</p></div><div class="panel"><h3 class="section-title">预览与数据管理</h3><p style="font-size:11px;color:#8c9e86;line-height:1.9">V2 使用独立数据，完全不影响原版作品。你可以清空此版本的演示记录，从头体验。</p><button class="text-btn" onclick="resetDemo()">重置 V2 演示数据</button></div></aside></div>`}
function saveProfile(e){e.preventDefault();const f=new FormData(e.target);for(const k of ['name','grade','skills','intro','experience'])state.profile[k]=f.get(k).trim();persist();renderProfile();toast('简历已保存，后续报名会展示更新后的信息')}
function editAvailability(){show(`<h2>先安排时间，再找到好兼职</h2><form onsubmit="event.preventDefault();state.profile.day=this.day.value;state.profile.distance=+this.distance.value;state.profile.min=+this.min.value;persist();modal.close();render();toast('求职期望已更新')"><label class="field">空闲日期<select name="day">${['不限','周六','周日'].map(x=>`<option ${profile().day===x?'selected':''}>${x}</option>`).join('')}</select></label><p>本演示可用时段固定为 09:00—18:00；所有岗位均位于该时段内。</p><label class="field">通勤范围<select name="distance">${[1,2,3,5].map(x=>`<option value="${x}" ${+profile().distance===x?'selected':''}>距校 ${x}km 内</option>`).join('')}</select></label><label class="field">最低时薪<select name="min">${[0,20,25,30,35,40].map(x=>`<option value="${x}" ${+profile().min===x?'selected':''}>${x?'¥'+x+'/小时':'不限'}</option>`).join('')}</select></label><button class="primary full">保存期望</button></form>`)}
function merchantJobs(){const ref=getJob(merchantShop)||base[0];return jobs().filter(j=>j.shop===ref.shop)}function merchantApps(){const ids=merchantJobs().map(j=>j.id);return state.apps.filter(a=>ids.includes(a.id)&&a.status!=='已取消')}
function renderMerchant(){const myJobs=merchantJobs(),apps=merchantApps(),shop=getJob(merchantShop)||base[0];const pending=apps.filter(a=>recruiting.includes(a.status)),settles=apps.filter(a=>a.status==='待结算');$('#app').innerHTML=`<div class="page-heading"><div><h1>商家工作台</h1><p>演示店铺：${esc(shop.shop)} · 负责人 ${shop.recruiter}</p></div><button class="primary" onclick="publishForm()">＋ 发布周末岗位</button></div><div class="notice">商家体验：<select aria-label="切换演示门店" style="border:1px solid #dce7d4;background:white;padding:7px;border-radius:5px;font-size:11px;color:#587d57" onchange="merchantShop=+this.value;renderMerchant()">${base.filter((j,i,all)=>all.findIndex(x=>x.shop===j.shop)===i).map(j=>`<option value="${j.id}" ${merchantShop===j.id?'selected':''}>${esc(j.shop)}</option>`).join('')}</select>　各门店只展示自己的岗位与报名。学生端报名后，在对应门店处理。</div><div class="metrics"><div class="metric"><small>招聘中的岗位</small><strong>${myJobs.filter(j=>!j.closed).length}</strong><em>已关闭岗位不在学生端推荐</em></div><div class="metric"><small>待处理报名</small><strong style="color:var(--orange)">${pending.length}</strong><em>先核对时间与学生意愿</em></div><div class="metric"><small>已录用待履约</small><strong>${apps.filter(a=>['待到岗','工作中'].includes(a.status)).length}</strong><em>明确任务，减少临时爽约</em></div><div class="metric"><small>待核对结算</small><strong>${settles.length}</strong><em>¥${settles.reduce((s,a)=>s+income(getJob(a.id)),0)} 约定班次金额</em></div></div><div class="merchant-tabs">${[['overview','工作台'],['candidates','报名管理'],['positions','岗位管理']].map(([v,t])=>`<button class="${merchantTab===v?'selected':''}" onclick="merchantTab='${v}';renderMerchant()">${t}</button>`).join('')}</div>${merchantTab==='overview'?`<div class="two-col"><section class="panel"><h3 class="section-title">今天要做的事</h3><div class="logic-grid"><div><b>${pending.length} 份报名待确认</b>筛选简历，安排面试或发送录用意向。<br><button class="text-btn" onclick="merchantTab='candidates';renderMerchant()">去处理 →</button></div><div><b>${settles.length} 个班次待结算</b>核对签到记录与约定工时。<br><button class="text-btn" onclick="merchantTab='candidates';renderMerchant()">核对结算 →</button></div></div><h3 class="section-title" style="margin-top:25px">一次周末用工闭环</h3><p style="font-size:11px;color:#82967c;line-height:2">发布岗位 → 投递简历 → 简历筛选 → 面试与结果 → 录用确认 → 到岗履约 → 工时结算。简单岗位可免面试快速录用。</p></section><section class="panel"><h3 class="section-title">运营关注什么</h3><p style="font-size:11px;line-height:2;color:#83967e">优先观察报名转录用、确认后到岗、工时争议和结算及时性。当前数据为单浏览器演示，无法据此计算真实转化或经营成效。</p><button class="secondary" onclick="productNotes()">查看产品与冷启动思路 ↗</button></section></div>`:merchantTab==='candidates'?candidateTable(apps):positionTable(myJobs)}`}
function candidateTable(apps){return apps.length?`<div class="table-wrap"><table><thead><tr><th>学生 / 岗位</th><th>班次</th><th>应聘进度</th><th>操作</th></tr></thead><tbody>${apps.map(a=>{const j=getJob(a.id);return `<tr><td><b>${esc(profile().name)}</b><small>${esc(j.title)}</small><button class="text-btn" onclick="studentResume(${j.id})">查看简历 ↗</button></td><td>${j.day} ${j.time}<small>¥${income(j)} / ${j.hours}小时</small></td><td><span class="status">${a.status}</span>${a.interview?`<small>${esc(a.interview.date)} ${esc(a.interview.time)}</small>`:''}</td><td class="candidate-actions">${a.status==='已投递'?`<button class="secondary" onclick="updateStatus(${j.id},'筛选中')">开始筛选</button>`:''}${['已投递','筛选中'].includes(a.status)?`<button class="primary" onclick="inviteInterview(${j.id})">邀请面试</button><button class="text-btn" onclick="hire(${j.id})">免面试录用</button>`:a.status==='待面试'?`<button class="primary" onclick="updateStatus(${j.id},'面试完成')">标记面试完成</button>`:a.status==='面试完成'?`<button class="primary" onclick="hire(${j.id})">面试通过 · 发送录用</button>`:a.status==='待结算'?`<button class="primary" onclick="settleShift(${j.id})">核对工时</button>`:`<small>${a.status==='待确认面试'?'等待学生确认面试':a.status==='待确认录用'?'等待学生接受录用':a.status==='已结算'?'履约已完成':terminal.includes(a.status)?'本次应聘已结束':'等待学生操作'}</small>`}${['已投递','筛选中','待确认面试','待面试','面试完成'].includes(a.status)?`<button class="text-btn reject" onclick="rejectApplication(${j.id})">不通过</button>`:''}</td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty"><strong>暂无应聘记录</strong><p>学生投递本门店岗位后，在这里筛选简历和安排面试。</p><button class="secondary" onclick="navigate('jobs')">查看学生端</button></div>`}
function inviteInterview(id){const j=getJob(id);show(`<h2>邀请面试</h2><p>${esc(profile().name)} · ${esc(j.title)}</p><form onsubmit="sendInterview(event,${id})"><div class="form-grid"><label class="field">面试日期<select name="date"><option>2026-10-30</option><option>2026-10-31</option><option>2026-11-01</option></select></label><label class="field">面试时间<select name="time"><option>09:00–09:15</option><option>10:00–10:15</option><option>11:00–11:15</option><option>14:00–14:15</option><option>16:00–16:15</option></select></label></div><label class="field">面试方式<select name="method"><option>门店面试</option><option>视频面试</option><option>电话沟通</option></select></label><label class="field">地点 / 接入说明<input name="location" required maxlength="100" value="${esc(j.place)}"></label><label class="field">补充说明<input name="note" maxlength="160" placeholder="例如：携带作品集，无需缴纳费用"></label><p>面试应在本班次开始前完成；当前只演示预约，不发送实际通知。</p><button class="primary full">发送面试邀请</button></form>`)}
function sendInterview(e,id){e.preventDefault();const f=new FormData(e.target),j=getJob(id),a=getApp(id);const start=Date.parse(f.get('date')+'T'+f.get('time').split('–')[0]+':00'),shift=Date.parse((j.day==='周六'?'2026-10-31':'2026-11-01')+'T'+String(j.start).padStart(2,'0')+':00:00');if(start+15*60000>shift){toast('面试必须在班次开始前完成，请调整日期或时间');return}a.interview={date:f.get('date'),time:f.get('time'),method:f.get('method'),location:f.get('location').trim(),note:f.get('note').trim()};updateStatus(id,'待确认面试');modal.close()}
function rejectApplication(id){show(`<h2>应聘未通过</h2><form onsubmit="event.preventDefault();getApp(${id}).rejection=this.reason.value;updateStatus(${id},'未通过');modal.close()"><label class="field">反馈原因<select name="reason"><option>岗位已招满</option><option>班次安排不匹配</option><option>岗位技能要求不匹配</option><option>本次暂不录用</option></select></label><p>反馈将同步展示给学生演示端。</p><button class="primary full">确认不通过</button></form>`)}

function positionTable(list){return `<div class="table-wrap"><table><thead><tr><th>岗位</th><th>班次 / 人数</th><th>时薪 / 状态</th><th>操作</th></tr></thead><tbody>${list.map(j=>`<tr><td><b>${j.icon} ${esc(j.title)}</b><small>${esc(j.shop)}</small></td><td>${j.day} ${j.time}<small>招募 ${j.slots} 人</small></td><td>¥${j.pay}/小时<small>${j.closed?'招聘已结束':'正在招募'}</small></td><td><button class="text-btn" onclick="togglePosition(${j.id})">${j.closed?'重新开放':'结束招聘'}</button><button class="text-btn" onclick="show(detailHTML(getJob(${j.id})))">查看</button></td></tr>`).join('')}</tbody></table></div>`}
function togglePosition(id){const j=getJob(id);j.closed=!j.closed;state.closedJobs=jobs().filter(j=>j.closed).map(j=>j.id);persist();renderMerchant();toast(j.closed?'已结束招聘，已有报名继续正常履约':'岗位已重新开放')}
function studentResume(id){show(`<h2>${esc(profile().name)}的演示简历</h2><p>${esc(profile().school)} · ${esc(profile().grade)}<br>技能：${esc(profile().skills||'暂未填写')}</p><h3>自我介绍</h3><p>${esc(profile().intro)}</p><h3>相关经历</h3><p>${esc(profile().experience||'暂未填写')}</p><div class="notice">仅展示当前演示角色资料。此页面不包含真实学生信息或联系方式。</div>${['已投递','筛选中','面试完成'].includes(getApp(id)?.status)?`<button class="primary full" onclick="modal.close();hire(${id})">发送录用意向</button>`:''}`)}
function hire(id){const j=getJob(id),a=getApp(id),fast=a.status!=='面试完成';show(`<h2>${fast?'免面试快速录用':'发送录用意向'}</h2><p>${esc(profile().name)} · ${esc(j.title)}<br>${j.day} ${j.time} · ${j.hours}小时<br>时薪 ¥${j.pay} · 本班收入 ¥${income(j)}</p><div class="notice">${fast?'该岗位选择免面试录用，求职进度会明确标注“免面试”。':'已完成面试，将发送录用结果。'}学生接受后才确认排班。此操作仅演示，不构成真实用工合同。</div><button class="primary full" onclick="getApp(${id}).fastTrack=${fast};updateStatus(${id},'待确认录用');modal.close()">发送演示录用意向</button>`)}

function settleShift(id){const j=getJob(id);show(`<h2>工时核对与模拟结算</h2><p>${esc(profile().name)} · ${esc(j.title)}<br>${j.day} ${j.time}<br>演示签到签退对应约定 ${j.hours} 小时</p><div class="wage-box"><div class="line"><span>时薪 × 工时</span><span>¥${j.pay} × ${j.hours}</span></div><div class="line total"><span>本班应付</span><b>¥${income(j)}</b></div></div><div class="notice orange">此操作只更新浏览器内的模拟账目，不进行真实付款。真实上线需双方核实实际工时与支付结果。</div><button class="primary full" onclick="updateStatus(${id},'已结算');modal.close()">确认工时 · 模拟结算 ¥${income(j)}</button>`)}
function publishForm(){const ref=getJob(merchantShop);show(`<h2>发布一个周末好岗位</h2><p>${esc(ref.shop)} · ${ref.recruiter}</p><form onsubmit="publishPosition(event)"><label class="field">岗位名称<input name="title" maxlength="24" required placeholder="例如：周末门店伙伴"></label><div class="form-grid"><label class="field">岗位类型<select name="category"><option>餐饮零售</option><option>活动协助</option><option>技能兼职</option><option>文教助教</option><option>办公协助</option><option>运动服务</option><option>校园服务</option></select></label><label class="field">工作日期<select name="day"><option>周六</option><option>周日</option></select></label><label class="field">开始时间<select name="start">${[9,10,11,12,13,14].map(n=>`<option value="${n}">${n}:00</option>`).join('')}</select></label><label class="field">约定工时<select name="hours"><option value="4">4小时</option><option value="3">3小时</option></select></label><label class="field">时薪（20—100元）<input name="pay" required type="number" min="20" max="100" step="1" value="25"></label><label class="field">招聘人数<input name="slots" required type="number" min="1" max="20" step="1" value="2"></label><label class="field wide">具体工作内容<textarea name="description" required maxlength="180" placeholder="请明确具体工作任务，不写笼统的“服从安排”"></textarea></label></div><label class="checkbox"><input type="checkbox" name="beginner" checked>无需经验，新人可报名</label><label class="checkbox"><input type="checkbox" name="meal">提供工作餐</label><label class="checkbox"><input type="checkbox" required>演示承诺：不收押金或报名费，工时确认后次日结算</label><button class="primary full">发布演示岗位</button></form>`)}
function publishPosition(e){e.preventDefault();const f=new FormData(e.target),ref=getJob(merchantShop),start=+f.get('start'),hours=+f.get('hours'),title=f.get('title').trim(),desc=f.get('description').trim();if(!title||!desc){toast('请填写具体岗位名称与工作内容');return}state.custom.push({id:Date.now(),shop:ref.shop,recruiter:ref.recruiter,reply:ref.reply,place:ref.place,title,cat:f.get('category'),pay:+f.get('pay'),day:f.get('day'),start,end:start+hours,hours,time:`${String(start).padStart(2,'0')}:00–${String(start+hours).padStart(2,'0')}:00`,dist:ref.dist,slots:+f.get('slots'),desc,requirements:f.get('beginner')?'无需相关经验，能按时到岗、认真完成任务。':'需要相关基础经验，请在沟通中说明。',icon:ref.icon,bg:ref.bg,tags:[...(f.get('beginner')?['新人友好']:['需基础经验']),...(f.get('meal')?['提供工作餐']:[]),'新发布'],settlement:'次日结算'});persist();modal.close();merchantTab='positions';renderMerchant();toast('演示岗位已发布，学生端立即可见')}
function reportJob(id){show(`<h2>反馈岗位或履约问题</h2><p>${esc(getJob(id).title)}</p><form onsubmit="event.preventDefault();state.reports=state.reports||[];state.reports.push({job:${id},type:this.type.value,note:this.note.value.trim()});persist();modal.close();toast('演示反馈已记录；不会提交至实际客服')"><label class="field">问题类型<select name="type"><option>要求押金或报名费</option><option>薪资或工作内容不一致</option><option>工时记录有异议</option><option>商家身份可疑</option><option>其他问题</option></select></label><label class="field">具体情况<textarea name="note" required maxlength="250" placeholder="请描述问题，勿输入真实隐私信息"></textarea></label><div class="notice">此功能仅展示反馈流程，不接入真实客服。真实上线需案件记录、处理时限与申诉机制。</div><button class="primary full">提交演示反馈</button></form>`)}
function campusInfo(){show(`<h2>从一个校园生活圈开始</h2><p>当前选择：江城大学（虚构演示校园）。<br>围绕校园生活圈展示短期门店与活动用工，降低通勤和信息搜寻成本。</p><div class="notice">当前仅有一个演示校园；地名与距离均为模拟信息。此版本不接入地图定位或实际导航。</div><button class="primary full" onclick="modal.close()">了解了</button>`)}
function safetyGuide(){show(`<h2>先把约定说清楚，<br>再安心去上班。</h2><h3>① 不为一份兼职，先付一笔钱</h3><p>遇到押金、培训费、材料费或要求转账到个人账号，请停止操作并举报。不要发送银行卡密码、验证码或证件照片。</p><h3>② 看清班次，也看清工资</h3><p>确认起止时间、工作内容、具体地点、时薪和结算节点。新增任务或延长工时，先与商家重新确认并保留记录。</p><h3>③ 过程可追，问题有记录</h3><p>到岗、签退和工时确认应有双方可查的记录。对工时或薪资有异议时，先提交问题，再继续核对。</p><div class="notice orange">本作品所有岗位、资料核验、对话、签到、客服与结算均为模拟功能。数据仅保存在当前浏览器，不提供真实用工、支付或安全保障。</div><h3>关于隐私</h3><p>用虚构资料即可体验。不会收集真实证件或支付信息，不请求定位、摄像头或通讯录权限。不同设备之间的数据不共享。</p>`)}
function resetDemo(){show(`<h2>重置 V2 演示数据？</h2><p>清空此浏览器中 V2 的报名、对话、收藏、简历修改和模拟收入。原版网站及其数据不会改变。</p><div class="actions"><button class="secondary" onclick="modal.close()">保留数据</button><button class="primary" onclick="localStorage.removeItem('zhoumo-preview-v2');location.reload()">重置演示</button></div>`)}
function productNotes(){show(`<div class="eyebrow">PRODUCT THINKING / V2</div><h2>从“信息撮合”到<br>“每个周末顺利上好一班”</h2><p>目标用户：周末有空、缺少经验且通勤半径有限的大学生；以及校园周边短时缺人、希望快速确认人手的商家。</p><h3>借鉴成熟招聘体验，适配周末兼职</h3><p>参考 BOSS 直聘的直接沟通、双向匹配，以及招聘网站常见的结构化职位、筛选、简历和收藏。将比较单位从“长期职位”缩小为“一个明确班次”。</p><div class="logic-grid"><div><b>找得准</b>时间、距离、时薪先筛选；岗位列表与详情并排，减少跳转。</div><div><b>聊得清</b>对话始终关联具体岗位，快捷确认经验、任务与结算，沟通后再报名。</div><div><b>比得明白</b>收藏、两岗对比、班次总收入与薪资拆解，降低学生选择成本。</div><div><b>到得了、结得清</b>报名冲突拦截、录用后排班、签到签退、工时确认与评价闭环。</div></div><h3>冷启动怎么做</h3><p>从一个校园和周边生活圈起步，优先招募任务可标准化的餐饮零售、活动协助岗位。商家明确固定班次与薪资，校内渠道引入首批学生，用首班履约反馈优化岗位信息。</p><h3>看哪些指标</h3><p>有效岗位覆盖、报名转录用率、确认后的到岗率、工时争议率、结算及时率与再次报名。当前本地模拟数据不构成真实业务成效。</p><h3>当前能力与上线边界</h3><p>前端交互原型：独立收藏、对比、简历、规则匹配、模拟直聊、报名、门店录用和结算可完整操作。未接入多用户数据库、真实聊天、地图、身份核验、通知和支付。真实上线需补齐这些能力以及商家审核和争议处理。</p><h3>预览发布约定</h3><p>V2 通过独立仓库与独立地址预览，使用独立浏览器存储。你确认后才更新原提交网站。</p><p>设计参考：<a href="https://www.zhipin.com/web/common/protocol/feature-intro.html" target="_blank" rel="noopener">BOSS 直聘官方功能介绍 ↗</a> · <a href="https://www.liepin.com/" target="_blank" rel="noopener">猎聘 ↗</a></p><button class="primary full" onclick="modal.close()">开始体验新版</button>`)}
state.apps.forEach(a=>{if(a.status==='待录用')a.status='已投递';if(stageList.includes(a.status)&&a.fastTrack===undefined)a.fastTrack=true});
(state.closedJobs||[]).forEach(id=>{const j=getJob(id);if(j)j.closed=true});modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});navigate('jobs');
